s=s.replace('<option value="0">Tous les débits disponibles</option><option value="0.01">À partir de 0,01 m³/s</option><option value="0.1">À partir de 0,1 m³/s</option><option value="1">À partir de 1 m³/s</option><option value="10">À partir de 10 m³/s</option><option value="100">À partir de 100 m³/s</option>','<option value="all">Tous les débits</option><option value="range:0:0.1">Moins de 0,1 m³/s</option><option value="range:0.1:1">De 0,1 à 1 m³/s</option><option value="range:1:10">De 1 à 10 m³/s</option><option value="range:10:100">De 10 à 100 m³/s</option><option value="range:100:1000000000">100 m³/s et plus</option>')
needle='<div id="tooltip" hidden></div><div class="map-hint">'
